import { Order, OrderState, OrderItem, StockReservation, OrderStateTransitions } from './types';
import { InvalidStateTransitionError, InsufficientStockError } from './errors';

export class OrderDomainService {
  private reservations: Map<string, StockReservation[]> = new Map();

  canTransition(fromState: OrderState, toState: string): boolean {
    return OrderStateTransitions[fromState].includes(toState as OrderState);
  }

  validateTransition(fromState: OrderState, toState: string): void {
    if (!this.canTransition(fromState, toState)) {
      throw new InvalidStateTransitionError(fromState, toState);
    }
  }

  reserveStock(orderId: string, items: OrderItem[], checkStock: (productId: string, quantity: number) => boolean): void {
    const validItems: StockReservation[] = [];

    for (const item of items) {
      if (!checkStock(item.productId, item.quantity)) {
        this.clearReservations(orderId);
        throw new InsufficientStockError(item.productId, item.quantity, 0);
      }
      validItems.push({ productId: item.productId, quantity: item.quantity });
    }

    this.reservations.set(orderId, validItems);
  }

  releaseReservations(orderId: string): StockReservation[] {
    const reserved = this.reservations.get(orderId) || [];
    this.reservations.delete(orderId);
    return reserved;
  }

  private clearReservations(orderId: string): void {
    this.reservations.delete(orderId);
  }

  getReservedItems(orderId: string): StockReservation[] {
    return this.reservations.get(orderId) || [];
  }
}

